var e=new LifeEngine();e.Borders=true;e.LoadPattern(Catalog.All[8]);var block=(byte[])e.Cells.Clone();for(int i=0;i<10;i++)e.Step(false);Check(e.Cells.SequenceEqual(block));e.LoadPattern(Catalog.All[7]);var blinker=(byte[])e.Cells.Clone();e.Step();Check(!e.Cells.SequenceEqual(blinker));e.Step();Check(e.Cells.SequenceEqual(blinker));e.Undo();Check(e.Generation==1);e.Undo();Check(e.Generation==0);e.LoadPattern(Catalog.All[0]);for(int i=0;i<4;i++)e.Step(false);Check(e.Population==5&&e.Cells[49*160+80]==1);e.Clear();e.Wrap=true;e.Set(159,0,true);e.Set(0,0,true);e.Set(1,0,true);e.Step();Check(e.Cells[99*160]==1&&e.Cells[0]==1&&e.Cells[160]==1);e.Undo();e.Wrap=false;e.Step(false);Check(e.Population==0);foreach(var (index,period) in new[]{(1,3),(6,15)}){e.LoadPattern(Catalog.All[index]);var seed=(byte[])e.Cells.Clone();for(int i=0;i<period;i++)e.Step(false);Check(e.Cells.SequenceEqual(seed));}for(int i=0;i<120;i++)e.Checkpoint();Check(e.History.Count==96);var reset=new LifeEngine();reset.LoadPattern(Catalog.All[0]);reset.Set(1,1,true);var initial=(byte[])reset.Cells.Clone();reset.Step();reset.Step();var restored=new LifeEngine();restored.Load(reset.Save());Check(restored.Generation==2&&restored.Cells.SequenceEqual(reset.Cells));restored.Restart();Check(restored.Generation==0&&restored.Cells.SequenceEqual(initial));var edits=new LifeEngine();edits.LoadPattern(Catalog.All[0]);edits.Step();var evolvedGrid=(byte[])edits.Cells.Clone();edits.Checkpoint();edits.Set(1,1,true);edits.Undo();Check(edits.Generation==1&&edits.Cells.SequenceEqual(evolvedGrid));edits.Checkpoint();edits.Set(2,2,true);edits.Back();Check(edits.Generation==0&&edits.Population==5);edits.Redo();Check(edits.Generation==1&&edits.Cells[2*160+2]==1);edits.Undo();edits.Checkpoint();edits.Set(3,3,true);Check(edits.Redos.Count==0);edits.Borders=true;edits.CursorX=edits.CursorY=0;edits.MoveCursor(-1,0,false);Check(edits.CursorX==0);edits.MoveCursor(1,0,true);edits.MoveCursor(0,1,true);Check(edits.Selected.SetEquals(new[]{0,1,161}));edits.Clear();edits.Selected=new HashSet<int>{0,1,161};edits.EditSelection(1);Check(edits.Population==3);edits.EditSelection(2);Check(edits.Population==0);edits.Undo();Check(edits.Population==3);edits.Redo();Check(edits.Population==0);edits.EditSelection(1);edits.EditSelection(0);Check(edits.Population==0);edits.Selected.Clear();edits.EditSelection(2);Check(edits.Population==1);edits.EditSelection(2);Check(edits.Population==0);var copy=new LifeEngine();copy.Load(e.Save());Check(copy.Cells.SequenceEqual(e.Cells)&&copy.Generation==e.Generation);try{copy.Load("{\"rows\":4,\"cols\":4,\"grid\":[]}");throw new Exception("Invalid file accepted");}catch(FormatException){}if(args.Length>0){copy.Load(File.ReadAllText(args[0]));Check(copy.Population==12&&copy.Generation==15);File.WriteAllText(args[1],copy.Save());}Console.WriteLine("C# engine: still life, oscillator, glider, wrap, undo, periods, history, JSON validation and Swift interoperability passed.");

