infinity.Clear();infinity.Set(-10,-10,true);infinity.Set(-9,-10,true);infinity.Select(-10,-10);infinity.Select(-9,-10);var rows=infinity.CopiedRows()!;infinity.Set(900,900,true);infinity.Place(rows,-40,-50);Check(infinity.Alive(-41,-50)&&infinity.Alive(-40,-50)&&infinity.Alive(900,900));infinity.Undo();Check(!infinity.Alive(-41,-50)&&infinity.Alive(900,900));infinity.Redo();infinity.ConfigureBorders(true,20,20);Check(infinity.Population==0);infinity.Undo();Check(!infinity.Borders&&infinity.Alive(900,900)&&!infinity.Document().V2Compatible);infinity.Clear();infinity.ConfigureBorders(true,5,5);infinity.ConfigureRules(0,0,8);infinity.Set(2,2,true);infinity.Step();Check(infinity.Alive(2,2)&&infinity.Equilibrium);infinity.ConfigureRules(2,3,3);infinity.Step();Check(infinity.Population==0);infinity.Randomize(1);Check(infinity.Population==25);infinity.Randomize(0);Check(infinity.Population==0);Console.WriteLine("C# infinite coordinates, border undo, clipboard placement, editable rules, equilibrium, density endpoints and sparse Swift interoperability passed.");

